if ($input.all().length !== 1) throw new Error('Run one refund request at a time.');
const r = $input.first().json;
if (typeof r.authorizationId !== 'string' || !/^auth_[A-Za-z0-9_-]+$/.test(r.authorizationId)) throw new Error('Set a stored Allowly authorization ID.');
if (typeof r.refundRequestId !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(r.refundRequestId)) throw new Error('Use a stable refund request ID of 1-64 ASCII letters, digits, hyphens or underscores.');
if (typeof r.paymentIntentId !== 'string' || !/^pi_[A-Za-z0-9]{1,80}$/.test(r.paymentIntentId)) throw new Error('Set a Stripe test PaymentIntent ID.');
if (!Number.isSafeInteger(r.amountMinor) || r.amountMinor < 1 || r.amountMinor > 99999999) throw new Error('amountMinor must be a positive integer, at most 99999999.');
if (r.currency !== 'usd' || r.reason !== 'requested_by_customer') throw new Error('This example supports USD customer-requested refunds only.');
if (typeof r.customerMessageId !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(r.customerMessageId)) throw new Error('customerMessageId must be an opaque ID of 1-64 ASCII letters, digits, hyphens or underscores.');
if (typeof r.customerMessage !== 'string' || r.customerMessage !== r.customerMessage.trim() || r.customerMessage.length < 1 || r.customerMessage.length > 2000 || /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/.test(r.customerMessage)) throw new Error('customerMessage must be 1-2000 trimmed text characters without control characters.');
if (r.jevMode !== 'mock' && r.jevMode !== 'live') throw new Error('jevMode must be exactly mock or live.');
if (r.jevMode === 'mock' && r.customerMessage !== 'I was charged twice for September. Please refund the duplicate charge.') throw new Error('Mock mode is a fixed fixture. Keep its sample message unchanged or switch to live mode.');
return [{json:{authorizationId:r.authorizationId,refundRequestId:r.refundRequestId,paymentIntentId:r.paymentIntentId,amountMinor:r.amountMinor,currency:r.currency,reason:r.reason,customerMessageId:r.customerMessageId,customerMessage:r.customerMessage,jevMode:r.jevMode}}];

const p = $input.first().json;
const r = $('Validate request').first().json;
if (p.object !== 'payment_intent' || p.id !== r.paymentIntentId || p.livemode !== false) throw new Error('A matching Stripe test-mode PaymentIntent is required; live or malformed responses stop here.');
if (p.status !== 'succeeded' || p.currency !== r.currency || !Number.isSafeInteger(p.amount_received) || r.amountMinor > p.amount_received) throw new Error('Use a succeeded USD test payment with enough received funds.');
return [{json:r}];

const response = $input.first().json;
const r = $('Validate request').first().json;
const reasons = ['duplicate_charge','defective_or_damaged','not_received','changed_mind','unauthorized','other_or_unclear'];
const autoReasons = new Set(['duplicate_charge','defective_or_damaged','not_received','changed_mind']);
const unit = (name, value) => { if (typeof value !== 'number' || !Number.isFinite(value) || value < 0 || value > 1) throw new Error(name + ' must be a finite number from 0 to 1.'); return value; };
if (!response || typeof response !== 'object' || Array.isArray(response)) throw new Error('Jev returned no decision object.');
if (r.jevMode === 'mock') {
  if (response.model !== 'typesafe/jev-1.13-mock' || response.provider !== 'Allowly demo fixture' || response.id !== 'mock-jev-refund-001') throw new Error('Unexpected mock Jev fixture.');
} else {
  if (typeof response.model !== 'string' || !/^typesafe\/jev-1\.13(?:-[0-9]{8})?$/.test(response.model)) throw new Error('OpenRouter did not return the pinned Jev 1.13 family.');
  if (response.provider !== 'TypeSafe' || typeof response.id !== 'string' || !/^gen-dec-[A-Za-z0-9_-]{1,200}$/.test(response.id)) throw new Error('OpenRouter returned unexpected Jev provenance.');
}
if (!response.answers || typeof response.answers !== 'object' || Array.isArray(response.answers) || Object.keys(response.answers).sort().join(',') !== 'refund_reason,refund_requested') throw new Error('Jev must return exactly the two requested answers.');
const requested = response.answers?.refund_requested;
const reason = response.answers?.refund_reason;
if (requested?.type !== 'noul' || reason?.type !== 'choice' || !reasons.includes(reason.choice)) throw new Error('Jev returned unexpected answer types or reason.');
const refundRequested = unit('refund_requested.noul', requested.noul);
const confidence = unit('refund_reason.confidence', reason.confidence);
if (!reason.probabilities || typeof reason.probabilities !== 'object' || Array.isArray(reason.probabilities) || Object.keys(reason.probabilities).sort().join(',') !== [...reasons].sort().join(',')) throw new Error('Jev must return one probability for every refund reason.');
const probabilities = reasons.map((key) => unit('refund_reason.probabilities.' + key, reason.probabilities[key]));
if (Math.abs(probabilities.reduce((sum, value) => sum + value, 0) - 1) > 0.03) throw new Error('Jev reason probabilities must sum to approximately 1.');
const selectedProbability = reason.probabilities[reason.choice];
if (selectedProbability + 0.01 < Math.max(...probabilities)) throw new Error('Jev selected a reason outside the highest-probability band.');
const usage = response.usage;
if (!usage || !Number.isSafeInteger(usage.input_tokens) || usage.input_tokens < 0 || !Number.isSafeInteger(usage.output_tokens) || usage.output_tokens < 0 || typeof usage.cost !== 'number' || !Number.isFinite(usage.cost) || usage.cost < 0) throw new Error('Jev returned invalid usage data.');
const jev = {
  decisionSource:r.jevMode === 'mock' ? 'mock_fixture' : 'openrouter_live',
  triageContract:'refund_triage_v1',
  jevGenerationId:response.id,
  jevModel:response.model,
  jevProvider:response.provider,
  refundRequestedPpm:Math.round(refundRequested * 1000000),
  refundReason:reason.choice,
  refundReasonProbabilityPpm:Math.round(selectedProbability * 1000000),
  refundReasonConfidencePpm:Math.round(confidence * 1000000),
  refundReasonProbabilitiesPpm:Object.fromEntries(reasons.map((key) => [key, Math.round(reason.probabilities[key] * 1000000)])),
  usage:{inputTokens:usage.input_tokens,outputTokens:usage.output_tokens,costMicrousd:Math.round(usage.cost * 1000000)},
};
jev.triageRoute = jev.refundRequestedPpm <= 100000 ? 'not_requested' : jev.refundRequestedPpm >= 900000 && jev.refundReason !== 'other_or_unclear' && jev.refundReasonConfidencePpm >= 800000 && jev.refundReasonProbabilityPpm >= 600000 ? 'ready_for_allowly' : 'manual_review';
const context = {refund_request_id:r.refundRequestId,customer_message_id:r.customerMessageId,payment_intent_id:r.paymentIntentId,amount_minor:r.amountMinor,currency:r.currency,reason:r.reason,triage_source:jev.decisionSource,jev_generation_id:jev.jevGenerationId,jev_model:jev.jevModel,jev_provider:jev.jevProvider,refund_requested_ppm:jev.refundRequestedPpm,refund_reason:jev.refundReason,refund_reason_probability_ppm:jev.refundReasonProbabilityPpm,refund_reason_confidence_ppm:jev.refundReasonConfidencePpm,triage_route:jev.triageRoute};
const resource = ['stripe-refund',r.refundRequestId,r.customerMessageId,r.paymentIntentId,r.amountMinor,r.currency,r.reason,jev.decisionSource,jev.jevGenerationId,jev.jevModel,jev.refundRequestedPpm,jev.refundReason,jev.refundReasonProbabilityPpm,jev.refundReasonConfidencePpm,jev.triageRoute,jev.triageContract].join(':');
return [{json:{authorizationId:r.authorizationId,refundRequestId:r.refundRequestId,customerMessageId:r.customerMessageId,paymentIntentId:r.paymentIntentId,amountMinor:r.amountMinor,currency:r.currency,reason:r.reason,resource,stripeIdempotencyKey:'allowly-refund:' + r.refundRequestId,context,jev}}];

const d = $input.first().json;
const result = d.results?.['refund.create'];
if (d.action !== 'refund.create' || !['allow','deny','confirm','escalate'].includes(d.decision) || result?.decision !== d.decision) throw new Error('Invalid Allowly decision; no refund.');
const receiptId = d.receipt?.receipt_id ?? d.receipt?.receipt?.receipt_id;
if (typeof receiptId !== 'string' || !/^rcp_[A-Za-z0-9_-]+$/.test(receiptId)) throw new Error('Missing decision receipt; no refund.');
if (d.decision === 'confirm' && (typeof d.confirmNonce !== 'string' || !d.confirmNonce)) throw new Error('Missing confirmation nonce.');
if (d.decision === 'escalate' && (typeof d.escalationId !== 'string' || !d.escalationId)) throw new Error('Missing escalation ID.');
return [{json:{...d, receiptId}}];

const body = $input.first().json.body;
const request = $('Freeze Jev decision').first().json;
if (!body || typeof body !== 'object' || Array.isArray(body) || Object.keys(body).sort().join(',') !== 'approved,resource') throw new Error('Review missing, timed out, or has unexpected fields.');
if (typeof body.approved !== 'boolean' || body.resource !== request.resource) throw new Error('Review must contain an explicit boolean and the exact frozen refund resource.');
return [{json:{approved:body.approved}}];

const refund = $input.first().json;
const permitted = $('Refund permitted').first().json;
const r = permitted.request;
if (refund.object !== 'refund' || typeof refund.id !== 'string' || !/^re_[A-Za-z0-9]+$/.test(refund.id) || refund.payment_intent !== r.paymentIntentId || refund.amount !== r.amountMinor || refund.currency !== r.currency || typeof refund.status !== 'string') throw new Error('Unexpected refund response. Reconcile in Stripe before retrying; keep the same request ID.');
return [{json:{request:r,decision:permitted.decision,stripeRefund:{id:refund.id,payment_intent:refund.payment_intent,amount:refund.amount,currency:refund.currency,status:refund.status},receiptVerification:'not_performed'}}];

const d = $input.first().json;
const receiptId = d.receipt?.receipt_id ?? d.receipt?.receipt?.receipt_id;
if (d.action !== 'refund.create' || d.decision !== 'allow' || d.results?.['refund.create']?.decision !== 'allow' || typeof receiptId !== 'string' || !/^rcp_[A-Za-z0-9_-]+$/.test(receiptId)) throw new Error('Fresh check did not allow this refund; start a new review.');
return [{json:{...d,receiptId}}];

const evidence = $('Refund result').first().json;
const envelope = $input.first().json;
const receiptId = envelope.receipt_id ?? envelope.receipt?.receipt_id;
if (!['signed','pending'].includes(envelope.status) || receiptId !== evidence.decision.receiptId) throw new Error('Unexpected receipt response. Keep Refund result and retrieve its receipt ID separately; do not create another refund.');
if (envelope.status === 'signed' && typeof envelope.receipt?.signature !== 'string') throw new Error('Signed receipt is missing its signature.');
return [{json:{...evidence,decisionReceipt:envelope,receiptPending:envelope.status === 'pending'}}];
